import fs from 'node:fs';import path from 'node:path';import readline from 'node:readline';import {createHash} from 'node:crypto';import {performance} from 'node:perf_hooks';import {createBookPublicationState,applyBookPublication} from '../live-paper/book-publication-v2.mjs';import {sealedNativePrefix} from '../live-paper/native-dip-host-v1.mjs';import {createInventoryQuoteWalletV1,advanceInventoryQuoteWalletV1,inventoryQuoteWalletReportV1} from '../paper/inventory-quote-wallet-v1.mjs';
const begun=performance.now(),rt=path.join(process.env.LOCALAPPDATA,'SigTradingCup','paper-runtime'),cutoff='2026-10-06T00:00:00.000Z',events=[],bindings={};let scope=null,state=null;
for(const name of['public-books.jsonl','anonymous-trades.jsonl']){const file=path.join(rt,name),seal=sealedNativePrefix(file),hash=createHash('sha256'),stream=fs.createReadStream(file,{end:seal.bytes-1});stream.on('data',b=>hash.update(b));let count=0,previous='',lastAt=null;for await(const line of readline.createInterface({input:stream,crlfDelay:Infinity})){const row=JSON.parse(line);count++;if(name==='public-books.jsonl'){if(!state){scope=row.payload.scope;state=createBookPublicationState(scope);}state=applyBookPublication(state,row);if(Date.parse(row.at)>=Date.parse(cutoff))events.push(row.kind==='book'?{kind:'book',at:row.at,book:row.payload.book,sequence:row.sequence,hash:row.hash}:{kind:'boundary',marketId:row.payload.marketId??null,at:row.at});}else{const{hash:expected,...body}=row;if(row.sequence!==count||row.previous!==previous||createHash('sha256').update(JSON.stringify(body)).digest('hex')!==expected||lastAt&&Date.parse(row.at)<Date.parse(lastAt))throw Error('TAPE_REPLAY_CHAIN');previous=expected;lastAt=row.at;const e=row.event;if(e.type!=='anonymous_trade_page'||e.tournamentId!==scope.tournamentId||!scope.exchanges.some(m=>m.marketId===e.marketId&&m.exchangeId===e.exchangeId))throw Error('TAPE_REPLAY_SCOPE');if(Date.parse(row.at)>=Date.parse(cutoff))events.push({kind:'trades',at:row.at,page:e});}}
 const s=fs.statSync(file);if(s.ino!==seal.ino||s.dev!==seal.dev||s.size<seal.bytes)throw Error('TAPE_REPLAY_REPLACED');bindings[name]={bytes:seal.bytes,sha256:hash.digest('hex'),records:count};}
events.sort((a,b)=>Date.parse(a.at)-Date.parse(b.at)||({boundary:0,book:1,trades:2}[a.kind]-{boundary:0,book:1,trades:2}[b.kind]));const base={cutoff,initialCash:'100.000000',maximumCommitted:'25.000000',maximumMarkets:12,maximumOrderCost:'5.000000',quantity:1,latencyMs:3000,lifetimeMs:120000,maximumGapMs:120000,minimumSamples:4,minimumHistoryMs:120000,depthFractionBps:100,horizonSeconds:300,fillModel:'strict_tape_through',requirePriorTape:true},policies=[0,5,10,20].map(riskAversion=>({...base,riskAversion,id:'tape-risk-'+riskAversion})),wallets=policies.map(createInventoryQuoteWalletV1);for(const event of events)for(let i=0;i<wallets.length;i++)advanceInventoryQuoteWalletV1(wallets[i],event,policies[i]);
const coverage={};for(const e of events.filter(e=>e.kind==='trades')){const x=coverage[e.page.exchangeId]??={pages:0,completePages:0,firstAt:e.at,lastAt:e.at};x.pages++;if(e.page.coverage?.complete&&e.page.pagination?.hasMore===false)x.completePages++;x.lastAt=e.at;}
const report={schemaVersion:1,createdAt:new Date().toISOString(),mode:'inventory_strict_tape_seen_capture_development_v1',bindings,processed:events.length,elapsedMs:performance.now()-begun,tradeCoverage:coverage,cohorts:policies.map((policy,i)=>({policy,report:inventoryQuoteWalletReportV1(wallets[i],policy),unresolvedQuotes:wallets[i].quotes.filter(q=>!q.closedAt),fills:wallets[i].fills,redemptions:wallets[i].redemptions})),networkRequests:0,competitionOrders:0,profitabilityEstablished:false,limitations:['Previouslyseen development captures, not holdout/prospective evidence.','Strict-through anonymous trades cannot prove actual queue priority or aggressor direction.','Unknown/censored quotes retain reservations; normal complementary netting is counterfactual.']};fs.writeFileSync('data/inventory-tape-replay-20261007.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({processed:events.length,elapsedMs:report.elapsedMs,cohorts:report.cohorts.map(x=>({id:x.policy.id,...x.report})),unresolved:report.cohorts[0].unresolvedQuotes.map(q=>({marketId:q.marketId,exchangeId:q.exchangeId,coverage:coverage[q.exchangeId]}))}));
